test('removeLine refuses to remove last line', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-01-15',
    status: 'draft',
    lines: [{ sku: 'DEV-HOUR', name: 'Development (hour)', qty: 10, unitPrice: 9500, vatRate: 21 }],
  };

  const result = removeLine(invoice, 'DEV-HOUR');

  assert.equal(result.ok, false);
