test('removeLine refuses to modify non-draft invoice', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-01-15',
    status: 'sent',
    lines: [
      { sku: 'DEV-HOUR', name: 'Development (hour)', qty: 10, unitPrice: 9500, vatRate: 21 },
      { sku: 'COPY-HOUR', name: 'Copywriting (hour)', qty: 2, unitPrice: 6000, vatRate: 21 },
    ],
  };

  const result = removeLine(invoice, 'COPY-HOUR');

  assert.equal(result.ok, false);
  assert.equal(result.error, 'NOT_DRAFT');
});

test('removeLine does not mutate original invoice', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-01-15',
    status: 'draft',
    lines: [
      { sku: 'DEV-HOUR', name: 'Development (hour)', qty: 10, unitPrice: 9500, vatRate: 21 },
      { sku: 'COPY-HOUR', name: 'Copywriting (hour)', qty: 2, unitPrice: 6000, vatRate: 21 },
    ],
  };

  const originalInvoice = JSON.stringify(invoice);
  removeLine(invoice, 'COPY-HOUR');

  assert.equal(JSON.stringify(invoice), originalInvoice);
});

test('removeLine preserves other properties', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-01-15',
    status: 'draft',
    lines: [
      { sku: 'DES-HOUR', name: 'Design work (hour)', qty: 5, unitPrice: 8500, vatRate: 21 },
      { sku: 'DEV-HOUR', name: 'Development (hour)', qty: 10, unitPrice: 9500, vatRate: 21 },
    ],
  };

  const result = removeLine(invoice, 'DEV-HOUR');

  assert.equal(result.value.customerId, 'C-001');
  assert.equal(result.value.issueDate, '2026-01-15');
  assert.equal(result.value.status, 'draft');
});

test('addLine can be chained to build an invoice', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-01-15',
    status: 'draft',
    lines: [],
  };

  const result1 = addLine(invoice, { sku: 'DEV-HOUR', qty: 5 });
  assert.equal(result1.ok, true);

  const result2 = addLine(result1.value, { sku: 'COPY-HOUR', qty: 2 });
  assert.equal(result2.ok, true);
  assert.equal(result2.value.lines.length, 2);

  const result3 = addLine(result2.value, { sku: 'DEV-HOUR', qty: 3 });
  assert.equal(result3.ok, true);
  assert.equal(result3.value.lines.length, 2);
  assert.equal(result3.value.lines[0].qty, 8);
});

